// RSS feeds across 4 categories
const feeds = [
  // Tech (source_category: tech) — last 3 days
  { name: 'MIT Technology Review', url: 'https://www.technologyreview.com/feed/', category: 'tech' },
  { name: 'The Verge AI', url: 'https://www.theverge.com/ai-artificial-intelligence/rss/index.xml', category: 'tech' },
  { name: 'Wired', url: 'https://feeds.wired.com/wired/index', category: 'tech' },
  { name: 'Ars Technica', url: 'https://feeds.arstechnica.com/arstechnica/index', category: 'tech' },
  { name: 'VentureBeat AI', url: 'https://venturebeat.com/category/ai/feed/', category: 'tech' },
  { name: 'Digi.no', url: 'https://www.digi.no/rss', category: 'tech' },

  // Economy/market (source_category: economy) — last 3 days
  { name: 'Reuters Business', url: 'https://feeds.reuters.com/reuters/businessNews', category: 'economy' },
  { name: 'Reuters Tech', url: 'https://feeds.reuters.com/reuters/technologyNews', category: 'economy' },
  { name: 'E24', url: 'https://e24.no/rss/', category: 'economy' },
  { name: 'DN', url: 'https://www.dn.no/rss/', category: 'economy' },
  { name: 'Quartz', url: 'https://qz.com/feed', category: 'economy' },
  { name: 'Finansavisen', url: 'https://www.finansavisen.no/rss/', category: 'economy' },

  // Regulation/policy (source_category: policy) — last 5 days
  { name: 'Euractiv Digital', url: 'https://www.euractiv.com/sections/digital/feed/', category: 'policy' },
  { name: 'Datatilsynet', url: 'https://www.datatilsynet.no/feed/', category: 'policy' },
  { name: 'IAPP', url: 'https://www.iapp.org/feed/', category: 'policy' },
  { name: 'Computer Weekly', url: 'https://www.computerweekly.com/rss/IT-security.xml', category: 'policy' },
  { name: 'EU AI Act', url: 'https://artificialintelligenceact.eu/feed/', category: 'policy' },

  // Organisation/leadership (source_category: leadership) — last 5 days
  { name: 'HBR', url: 'https://feeds.hbr.org/harvardbusiness', category: 'leadership' },
  { name: 'McKinsey Insights', url: 'https://www.mckinsey.com/insights/rss', category: 'leadership' },
  { name: 'MIT Sloan', url: 'https://sloanreview.mit.edu/feed/', category: 'leadership' },
  { name: 'strategy+business', url: 'https://www.strategy-business.com/rss', category: 'leadership' },
  { name: 'Khrono', url: 'https://www.khrono.no/rss', category: 'leadership' }
];

// Per-category day cutoffs
const dayCutoffs = { tech: 3, economy: 3, policy: 5, leadership: 5 };
const capPerCategory = 10;
const now = new Date();

// Collect articles grouped by category
const articlesByCategory = { tech: [], economy: [], policy: [], leadership: [] };

for (const feed of feeds) {
  try {
    const cutoffDate = new Date(now);
    cutoffDate.setDate(cutoffDate.getDate() - dayCutoffs[feed.category]);

    const xml = await this.helpers.httpRequest({
      method: 'GET',
      url: feed.url,
      headers: { 'Accept': 'application/rss+xml, application/xml, text/xml' },
      returnFullResponse: false,
      timeout: 10000
    });

    // Simple regex-based XML parsing (no DOMParser in n8n Code nodes)
    const items = xml.match(/<item[\s\S]*?<\/item>/gi) || [];

    for (const item of items) {
      const titleMatch = item.match(/<title><!\[CDATA\[(.+?)\]\]><\/title>/) ||
                         item.match(/<title>(.+?)<\/title>/);
      const linkMatch = item.match(/<link><!\[CDATA\[(.+?)\]\]><\/link>/) ||
                        item.match(/<link>(.+?)<\/link>/);
      const descMatch = item.match(/<description><!\[CDATA\[(.+?)\]\]><\/description>/) ||
                        item.match(/<description>(.+?)<\/description>/);
      const dateMatch = item.match(/<pubDate>(.+?)<\/pubDate>/);

      if (!titleMatch || !linkMatch) continue;

      const pubDate = dateMatch ? new Date(dateMatch[1]) : new Date();
      if (pubDate < cutoffDate) continue;

      // Strip HTML tags from description
      const rawSummary = descMatch ? descMatch[1] : '';
      const summary = rawSummary.replace(/<[^>]+>/g, '').substring(0, 500);

      articlesByCategory[feed.category].push({
        title: titleMatch[1],
        url: linkMatch[1],
        summary,
        publishedAt: pubDate.toISOString(),
        source: feed.name,
        sourceCategory: feed.category
      });
    }
  } catch (e) {
    // Skip feeds that fail to fetch
  }
}

// Sort each category by date (newest first) and cap at capPerCategory
const articles = [];
for (const cat of Object.keys(articlesByCategory)) {
  const catArticles = articlesByCategory[cat];
  catArticles.sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime());
  articles.push(...catArticles.slice(0, capPerCategory));
}

// Sort combined by date and cap at 40 total
articles.sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime());
const capped = articles.slice(0, 40);

if (capped.length === 0) {
  return [];
}

return [{ json: { articles: capped } }];

const feedData = $input.first().json;

const agentResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://fyrk-agent-runtime.fly.dev/run/linkedin-post',
  headers: { 'Content-Type': 'application/json' },
  body: {
    version: '0.3',
    input: {
      articles: feedData.articles,
      topics: ['AI', 'automatisering', 'beslutningsverktøy'],
      maxPosts: 3,
      language: 'no',
      tone: 'thought-leader'
    },
    dryRun: false,
    publish: true
  },
  json: true,
  timeout: 60000
});

return [{ json: agentResponse }];

const data = $input.first().json;
const artifacts = data.artifacts || [];
const markdownArtifact = artifacts.find(a => a.kind === 'linkedin-post-drafts');

const drafts = data.output?.drafts || [];
const summary = `LinkedIn-utkast klare for gjennomgang:\n\n` +
  `Antall utkast: ${drafts.length}\n` +
  `Artikler analysert: ${data.output?.totalArticlesAnalyzed || 0}\n\n` +
  drafts.map((d, i) => {
    const format = d.visualFormat || 'tekst';
    const formatTag = format === '2x2-diagram' ? ' [2x2]' : '';
    return `${i + 1}. **${d.title}**${formatTag} (${(d.sourceArticles || []).map(a => a.source).join(', ')}) — ${d.characterCount} tegn`;
  }).join('\n');

return [{
  json: {
    summary,
    markdownContent: markdownArtifact?.content || '',
    draftsCount: drafts.length,
    runId: data.runId
  }
}];

const notification = $input.first().json;
const webhookUrl = $('Resolve Slack URL').first().json.slackWebhookUrl;

if (!webhookUrl) {
  throw new Error('SLACK_WEBHOOK_URL is not configured');
}

const data = $('Status OK?').first().json;
const drafts = data.output?.drafts || [];

// Build Block Kit blocks
const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: 'LinkedIn-utkast klare for gjennomgang',
      emoji: true
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${drafts.length} utkast* generert fra ${data.output?.totalArticlesAnalyzed || 0} artikler`
    }
  },
  { type: 'divider' }
];

for (const draft of drafts) {
  const format = draft.visualFormat || 'tekst';
  const formatLabel = format === '2x2-diagram' ? ' | Format: 2x2-diagram' : '';

  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${draft.title}*\nKilder: ${(draft.sourceArticles || []).map(a => a.source).join(', ')} — ${draft.characterCount} tegn${formatLabel}`
    }
  });
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `>${draft.postText.split('\n').join('\n>')}`
    }
  });

  // If 2x2-diagram, show diagram data
  if (format === '2x2-diagram' && draft.diagramData) {
    const d = draft.diagramData;
    blocks.push({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*2x2-diagram:* X: ${d.axisX} | Y: ${d.axisY}\nQ1: ${d.q1}\nQ2: ${d.q2}\nQ3: ${d.q3}\nQ4: ${d.q4}`
      }
    });
  }

  blocks.push({ type: 'divider' });
}

blocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: `Run ID: ${notification.runId} | ${new Date().toISOString()}`
    }
  ]
});

await this.helpers.httpRequest({
  method: 'POST',
  url: webhookUrl,
  headers: { 'Content-Type': 'application/json' },
  body: { blocks },
  json: true
});

return [{ json: { slackSent: true, draftsCount: drafts.length } }];
